def test_roundtrip_json_officepackagemanifest():
    """Test that load -> save -> load produces equivalent data."""
    json_data = r"""
    {
      "kind": "sample",
      "parts": [],
      "relationships": [],
      "contentTypes": []
    }
    """
    original_data = json.loads(json_data, strict=False)
    instance = OfficePackageManifest.load(original_data)
    saved_data = instance.save()
    reloaded = OfficePackageManifest.load(saved_data)
    assert reloaded is not None
    assert reloaded.kind == "sample"


